package anchors

import "testing"

// These independent expectations make removal of a ticket-lock obligation fail.
func TestTicketSlicingPasses(t *testing.T) {
	anchorHarness{group: AfterImplementSpec, rules: []anchorRule{
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", section: "Draft the breakdown", needle: "Before ticket lock, run a source-clause pass and an executable-route pass.", want: "ticket slicing: verification passes must precede ticket lock"},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", section: "Draft the breakdown", needle: "Assign each applicable source clause to a ticket or an explicit scope cut.", want: "ticket slicing: source clauses need a ticket or explicit scope cut"},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", section: "Draft the breakdown", needle: "Trace each claimed operation through its executable owner, using the [map-discipline proof rules](../bench-craft-spec/references/map-discipline.md#before-the-map-locks).", want: "ticket slicing: executable routes need their owner and canonical proof rules"},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", section: "Write one file per ticket", needle: "A ticket names every relocation destination in `Writes:`, including destinations for snapshots and registry rows.", want: "ticket slicing: relocation destinations belong in Writes"},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", section: "Draft the breakdown", needle: "A ticket that creates a seam its sibling tickets consume is its own review chunk, and that chunk stays small. Its chunk review closes before any consumer ticket starts. A seam the implementation introduces counts the same as a seam the spec declares.", want: "ticket slicing: a seam-creating ticket takes its own review chunk and closes review before its consumers"},
		{file: ".agents/skills/bench-craft-tickets/SKILL.md", section: "Write one file per ticket", needle: "Before you lock a `Writes:` line, read [the slicing checks](references/slicing-checks.md), which list every `Writes:` rule that the parser and build preflight enforce.", want: "ticket slicing: craft-tickets must point to the slicing checks"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Enforced rules", needle: "A `Writes:` entry for an anchored guidance path, or a directory above one, names every anchor registry file that names it, test files included.", want: "ticket slicing: the anchor closure rule is enforced"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Enforced rules", needle: "The spec's ownership fence equals the union of the ticket `Writes:` paths, less the review pickup and every path under the spec folder or `capture`.", want: "ticket slicing: the fence equals the Writes union"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A lane-check ticket proves its check through the real lane over a composed tree.", want: "ticket slicing: a lane check needs the real lane"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A posture change that reds a fixture helper makes the slicer list every call site of that helper before the map locks.", want: "ticket slicing: a fixture helper posture change lists every call site"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A combined behavior row belongs to the ticket that completes its final consumer.", want: "ticket slicing: a combined row belongs to its final consumer"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A retirement pass gives each sentence that grants the retired behavior its own forbid row and red-capable check.", want: "ticket slicing: each retired grant needs its own forbid row"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A cited verifier row names the exact checks it performed.", want: "ticket slicing: a verifier row names its exact checks"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "The slicer runs `bench preflight build <slug>` after each change to a ticket or an acceptance row.", want: "ticket slicing: build preflight reruns after each ticket or acceptance row change"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "The spec and its tickets go to sign-off and to their landing only on a green preflight of the current ticket graph.", want: "ticket slicing: sign-off and the landing wait for a green build preflight"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "Each acceptance claim names an available producer and an executable check at its ticket checkpoint.", want: "ticket slicing: each claim names its producer and check at its checkpoint"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A ticket that preserves or moves a ref names a check for each of the head, the tip, and the checked-out-ref shapes.", want: "ticket slicing: a ref move checks every ref shape"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A rule for one member of an enumerated family goes on its declaration row, and `Writes:` names the declaration table and its dispatch test.", want: "ticket slicing: a per-member rule fences its family declaration table and dispatch test"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A ticket that adds a second caller of another package's private rule names that package in `Writes:`, so one exported rule serves both callers.", want: "ticket slicing: a second caller of a private rule fences the rule's owner package"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Slicing rules", needle: "A ticket that changes a rendered output shape runs one `rg` for the old text, and each hit joins that ticket's own `Writes:` line.", want: "ticket slicing: a rendered-shape change sweeps every old-text reader into the ticket's Writes line"},
		{file: ".agents/skills/bench-craft-spec/references/map-discipline.md", section: "Before the map locks", needle: "A spec that adds an invariant check sweeps every input constructor of that check.", want: "map discipline: a new invariant check sweeps its input constructors"},
		{file: ".agents/skills/bench-craft-spec/references/map-discipline.md", section: "Before the map locks", needle: "Each input constructor satisfies the new invariant, or its file joins a ticket `Writes:` line.", want: "map discipline: each input constructor satisfies the invariant or joins Writes"},
		{file: ".agents/skills/bench-craft-spec/references/map-discipline.md", section: "Before the map locks", needle: "A spec that adds or removes a preflight row names every file that asserts the row count or the row list.", want: "map discipline: a preflight row change names every row-count reader"},
		{file: ".agents/skills/bench-craft-spec/references/map-discipline.md", section: "Before the map locks", needle: "A spec that changes the output of a fixture builder names every test that asserts or rewrites that output.", want: "map discipline: a fixture builder change names every output reader"},
		{file: ".agents/skills/bench-craft-spec/references/map-discipline.md", section: "Per row", needle: "The seam cell cites that function as `` `<path>_test.go` (`<Name>`) ``, so `bench coverage --check` and build preflight resolve the name against the tree.", want: "map discipline: an existing test seam cites its function in the resolvable form"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "Each research return lists every likely fence expansion in one of these classes:", want: "ticket slicing: chunk research lists each likely fence expansion by class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "Each entry cites its evidence as a `path:line` or as a command and its result.", want: "ticket slicing: each fence-expansion entry cites its evidence"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "- a caller file that `bench consumers` names;", want: "ticket slicing: fence-expansion evidence dropped the consumers caller class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "- a fixture or a canary that pins a path;", want: "ticket slicing: fence-expansion evidence dropped the pinning fixture class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "- an anchor registry file that names a guidance path;", want: "ticket slicing: fence-expansion evidence dropped the anchor registry class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "- a count pin, such as a package test-count pin;", want: "ticket slicing: fence-expansion evidence dropped the count pin class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "- a file over its structure budget, with its headroom;", want: "ticket slicing: fence-expansion evidence dropped the structure budget class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "- a shared file that more than one ticket writes, such as `CHANGELOG.md`.", want: "ticket slicing: fence-expansion evidence dropped the shared file class"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "Each path that a research return names goes into the ticket's `Writes:` line.", want: "ticket slicing: each research path goes into the ticket's Writes line"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "The slicer drops such a path only with `path:line` evidence that the path cannot change under any design.", want: "ticket slicing: a research path drops only on evidence that it cannot change"},
		{file: ".agents/skills/bench-craft-tickets/references/slicing-checks.md", section: "Fence-expansion evidence", needle: "`Writes:` is the approved upper bound of the ticket, not a task list.", want: "ticket slicing: Writes is the approved upper bound of the ticket"},
	}}.check(t)
}

// TestWriteSpecChunkedSlicing keeps the write-spec spec review, research round, per-chunk
// slicing, one ticket review, context checkpoint, review-line, and fence-narrowing rules
// red-capable. Each needle and diagnostic is written here independently of the registry, so
// a rewrite that drops a rule cannot define itself green. The moved-code guard, the witness
// cap, and the known-issues pointer to that cap have their rules here too.
func TestWriteSpecChunkedSlicing(t *testing.T) {
	const writeSpec = ".agents/commands/bench-write-spec.md"
	const implementSpec = ".agents/commands/bench-implement-spec.md"
	const line = ".agents/skills/bench-craft-line/SKILL.md"
	const issues = "docs/known-issues.md"
	anchorHarness{group: AfterImplementSpec, rules: []anchorRule{
		{file: writeSpec, section: "Process", needle: "After the spec fork returns, one independent review round grades the spec alone under `craft-spec`'s review rubric, its chunk table included.", want: "write-spec slicing: one independent round reviews the spec alone"},
		{file: writeSpec, section: "Process", needle: "It returns accept or reject, and slicing starts only after it accepts.", want: "write-spec slicing: slicing waits for the spec round to accept"},
		{file: writeSpec, section: "Process", needle: "After the spec review accepts, one research round charges two read-only readers for each chunk, with every chunk at the same time.", want: "write-spec slicing: one research round charges two readers for every chunk after the spec review"},
		{file: writeSpec, section: "Process", needle: "Each reader returns each likely fence expansion under the slicing checks' `Fence-expansion evidence` classes.", want: "write-spec slicing: each chunk's research returns its likely fence expansions"},
		{file: writeSpec, section: "Process", needle: "The invoking session merges each pair into one research table: the agreed set and the frontier.", want: "write-spec slicing: each reader pair merges into one research table"},
		{file: writeSpec, section: "Process", needle: "If the spec review changes the chunk table, the research reruns for each changed chunk.", want: "write-spec slicing: a changed chunk reruns its research"},
		{file: writeSpec, section: "Process", needle: "The slicer runs on `craft-line`'s ticket slicing line and slices the tickets one chunk at a time, in the order of the accepted chunk table.", want: "write-spec slicing: the slicer runs on the ticket slicing line, one chunk at a time"},
		{file: writeSpec, section: "Process", needle: "Each `Writes:` line keeps every research path under the slicing checks' keep rule.", want: "write-spec slicing: the command points to the slicing checks' keep rule"},
		{file: writeSpec, section: "Process", needle: "Compare each ticket's `Writes:` line with `bench preflight build <slug> --propose-writes` under the slicing checks.", want: "write-spec slicing: each chunk ticket's Writes line meets the propose-writes proposal"},
		{file: writeSpec, section: "Process", needle: "If the slicing session passes about 300k tokens of context, it compacts or restarts at a chunk boundary, never inside a chunk.", want: "write-spec slicing: the context checkpoint falls at a chunk boundary"},
		{file: writeSpec, section: "Process", needle: "The ledger holds the accepted tickets, the research table, the deferrals, the ordering edges, the spec flags, and the paths that wait for the fence.", want: "write-spec slicing: the context checkpoint carries its ledger"},
		{file: writeSpec, section: "Process", needle: "After the last chunk, one review round on `craft-line`'s ticket review line grades the whole ticket set under `craft-tickets`' granularity, edge, and merge-or-split quiz. Its iteration cap is 2.", want: "write-spec slicing: one ticket review round grades the whole ticket set after the last chunk"},
		{file: writeSpec, needle: "A delegate on `craft-line`'s chunk ticket review line grades the chunk's tickets.", want: "write-spec slicing: the retired review of each chunk returned", forbidden: true},
		{file: writeSpec, section: "Process", needle: "After the ticket review accepts, write the fence section. `bench preflight build <slug> --plan-only` then grades the whole ticket graph.", want: "write-spec slicing: the plan-only preflight grades the whole ticket graph after the ticket review"},
		{file: writeSpec, section: "Process", needle: "The invoking session repairs a rejected spec or ticket set, and the same round grades the repair alone.", want: "write-spec slicing: a rejected spec or ticket set is repaired and reviewed again alone"},
		{file: writeSpec, section: "Process", needle: "The count `<n>` sums the iterations of the spec round and of the ticket round.", want: "write-spec slicing: the verification log sums the iterations of every round"},
		{file: writeSpec, needle: "The invoking session coordinates the phase, slices the tickets, and presents the completed approval table to the reviewer.", want: "write-spec slicing: the invoking session slices the tickets"},
		{file: line, needle: "| Spec review (`/bench-write-spec`) | mid + medium |", want: "write-spec slicing: craft-line routes the spec review to mid + medium"},
		{file: line, needle: "| Ticket slicing (`/bench-write-spec`) | mid + high |", want: "write-spec slicing: craft-line routes the ticket slicing to mid + high"},
		{file: line, needle: "| Ticket review (`/bench-write-spec`) | mid + medium |", want: "write-spec slicing: craft-line routes the ticket review to mid + medium"},
		{file: line, needle: "| Chunk ticket review (`/bench-write-spec`) | cheap + high |", want: "write-spec slicing: craft-line kept the retired chunk ticket review row", forbidden: true},
		{file: line, needle: "When the invoking session runs on a model other than the mid binding, a fresh writer on the mid binding slices the tickets.", want: "write-spec slicing: craft-line sends the slicing to a fresh mid writer when the session model differs"},
		{file: implementSpec, needle: "The charge says that the author changes only what the acceptance needs.", want: "fence narrowing: the author charge limits the edit to what the acceptance needs"},
		{file: implementSpec, needle: "Before the first edit, the author lists every place the change must reach: callers, tests, fixtures, and exports.", want: "fence narrowing: the author lists the reach of the change before the first edit"},
		{file: implementSpec, needle: "The author's return names each untouched `Writes:` entry with a one-clause reason.", want: "fence narrowing: the author's return names each untouched Writes entry"},
		{file: implementSpec, needle: "The review charge says that an untouched `Writes:` entry is not a defect.", want: "fence narrowing: the review charge accepts an untouched Writes entry"},
		{file: implementSpec, needle: "An edit outside the acceptance's reach is a finding, even when its path is in `Writes:`.", want: "fence narrowing: the review charge finds an edit outside the acceptance's reach"},
		{file: implementSpec, needle: "Code that the author moves or merges keeps its error handling and validation.", want: "author charge: moved or merged code keeps its error handling and validation"},
		{file: implementSpec, needle: "A witness is one demonstrated red of one independent test expectation.", want: "witness cap: the author charge defines a witness"},
		{file: implementSpec, needle: "The charge caps the witnesses at one for each coverage row plus one for each production branch that the ticket adds.", want: "witness cap: the charge caps the witnesses by coverage rows and new production branches"},
		{file: implementSpec, needle: "The author meets the cap with fewer independent expectations, such as one table-driven test, and skips no witness.", want: "witness cap: the author meets the cap with fewer expectations and skips no witness"},
		{file: implementSpec, needle: "The author runs the floor checks and witnesses of several packages in one `bench test` call that repeats `--package`.", want: "witness cap: the author runs several packages in one bench test call"},
		{file: issues, needle: "Apply the witness cap and the batched `bench test` call that `/bench-implement-spec` states.", want: "witness cap: the known-issues row points to implement-spec for the cap"},
		{file: issues, needle: "Cap the witnesses in a charge", want: "witness cap: the known-issues row kept a copy of the cap", forbidden: true},
	}}.check(t)
}
